import time, json, os

class Music:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.gcode = self.printer.lookup_object("gcode")
        self.print_stats = self.printer.lookup_object("print_stats")
        self.config = config
        self.is_corexz = str(config.getsection("printer").get("kinematics")) == "corexz"
        self.is_corexy = str(config.getsection("printer").get("kinematics")) == "corexy"
        self.start_print_music = config.get("start_print_music", default="DEF_STRAT_PRINT_MUSIC")
        self.end_print_music = config.get("end_print_music", default="DEF_END_PRINT_MUSIC")
        self.power_on_music = config.get("power_on_music", default="DEF_POWER_ON_MUSIC")
        dir_switch_x = config.getint("dir_switch_x", default=5)
        dir_switch_y = config.getint("dir_switch_y", default=5)
        dir_switch_z = config.getint("dir_switch_z", default=5)
        step_us_x = config.getint("step_us_x", default=70)
        step_us_y = config.getint("step_us_y", default=70)
        step_us_z = config.getint("step_us_z", default=70)
        self.sound = config.getboolean("sound", default=True)
        self.fast = config.getfloat("fast", default=1.0)
        self.gcode.register_command("MUSIC", self.cmd_MUSIC)
        self.gcode.register_command("MUSIC_TO_POWER", self.cmd_MUSIC_TO_POWER)
        self.gcode.register_command("MUSIC_TO_START", (self.cmd_MUSIC_TO_START), desc=(self.cmd_MUSIC_TO_START_help))
        self.gcode.register_command("MUSIC_TO_END", (self.cmd_MUSIC_TO_END), desc=(self.cmd_MUSIC_TO_END_help))
        self.gcode.register_command("DEF_POWER_ON_MUSIC", self.cmd_DEF_POWER_ON_MUSIC)
        self.gcode.register_command("DEF_STRAT_PRINT_MUSIC", (self.cmd_DEF_STRAT_PRINT_MUSIC), desc=(self.cmd_DEF_STRAT_PRINT_MUSIC_help))
        self.gcode.register_command("DEF_END_PRINT_MUSIC", (self.cmd_DEF_END_PRINT_MUSIC), desc=(self.cmd_DEF_END_PRINT_MUSIC_help))
        self.gcode.register_command("SOUND_ON", self.cmd_SOUND_ON)
        self.gcode.register_command("SOUND_OFF", self.cmd_SOUND_OFF)
        self.ppins = self.printer.lookup_object("pins")
        self.swap_pin = self.ppins.parse_pin(config.getsection("stepper_x").get("step_pin"), True, True)
        self.mcu = self.swap_pin["chip"]
        self.oid = self.mcu.create_oid()
        self.mcu.register_config_callback(self._build_step_config)
        self.step_pins = {'x':[],  'y':[],  'z':[]}
        self.dir_pins = {'x':[],  'y':[],  'z':[]}
        for axis in ('x', 'y', 'z'):
            self.step_pins.setdefault(axis, [])
            self.dir_pins.setdefault(axis, [])
            sec = self.config.getsection(f"stepper_{axis}")
            if sec is None:
                raise self.printer.command_error(f"Missing configuration for stepper_{axis}")
            self.step_pins[axis].append(sec.get("step_pin"))
            self.dir_pins[axis].append(sec.get("dir_pin"))
            for s in (
             f"stepper_{axis}1", f"stepper_{axis}2", f"stepper_{axis}3"):
                self.gcode.respond_info("for s in [f'stepper_{axis}1', f'stepper_{axis}2', f'stepper_{axis}3']:")
                if self.config.has_section(s):
                    sec = self.config.getsection(s)
                    self.step_pins[axis].append(sec.get("step_pin"))
                    self.dir_pins[axis].append(sec.get("dir_pin"))

            if self.is_corexy:
                if axis == "y":
                    self.step_pins["x"].append(sec.get("step_pin"))
                    self.dir_pins["x"].append(sec.get("dir_pin"))
                if self.is_corexy:
                    if axis == "x":
                        self.step_pins["y"].append(sec.get("step_pin"))
                        self.dir_pins["y"].append(sec.get("dir_pin"))
                    self.file_path = os.path.join(os.path.dirname(self.printer.get_start_args()["config_file"]), "motor_sound_cfg.json")

        if not os.path.exists(self.file_path):
            data = {"sound": True} if self.sound else {"sound": False}
            os.makedirs((os.path.dirname(self.file_path)), exist_ok=True)
            with open(self.file_path, "w") as json_file:
                json.dump(data, json_file, indent=4)
        with open(self.file_path, "r") as json_file:
            data = json.load(json_file)
        self.sound = bool(data["sound"])

    def _build_step_config(self):
        self.gcode.respond_info("_build_step_config")
        self.toolhead = self.printer.lookup_object("toolhead")
        self.set_step_pin_num_cmd = self.mcu.lookup_command("set_step_pin_num x=%c y=%c z=%c", cq=None)
        self.get_time_us_cmd = self.mcu.lookup_query_command("get_time_us oid=%c time_us=%u", "get_time_us oid=%c time_us=%u", oid=(self.oid))
        self.set_step_pin_num_cmd.send([len(self.step_pins["x"]), len(self.step_pins["y"]), len(self.step_pins["z"])])
        self.control_step_freq_cmd = self.mcu.lookup_command("control_step_freq oid=%c dir=%c step_cnt=%u step_us=%u dir_swit=%u axis=%c", cq=None)
        self.timer_read_us = self.get_time_us_cmd.send([self.oid, 1])["time_us"]
        for axis in ('x', 'y', 'z'):
            self.step_pins[axis] = self.step_pins.get(axis, []) or []
            self.dir_pins[axis] = self.dir_pins.get(axis, []) or []
            if isinstance(self.step_pins[axis], str):
                self.step_pins[axis] = [
                 self.step_pins[axis]]
            if isinstance(self.dir_pins[axis], str):
                self.dir_pins[axis] = [
                 self.dir_pins[axis]]
            axis_index = ["x", "y", "z"].index(axis)
            for i in range(len(self.step_pins[axis])):
                step_par = self.ppins.parse_pin(self.step_pins[axis][i], True, True)
                dir_par = self.ppins.parse_pin(self.dir_pins[axis][i], True, True)
                if step_par:
                    if "pin" not in step_par or "invert" not in step_par:
                        raise ValueError(f"Invalid step_par: {step_par}, for pin: {self.step_pins[axis][i]}")
                    if dir_par and not "pin" not in dir_par and "invert" not in dir_par:
                        raise ValueError(f"Invalid dir_par: {dir_par}, for pin: {self.dir_pins[axis][i]}")
                    if axis == "x":
                        if self.is_corexy:
                            dir_invert = not bool(dir_par["invert"]) if (axis == "x") and (i == 0) else (bool(dir_par["invert"]))
                if axis == "y":
                    dir_invert = not bool(dir_par["invert"]) if self.is_corexy and axis == "y" and (i == 1) else (bool(dir_par["invert"]))
                elif axis == "z":
                    dir_invert = bool(dir_par["invert"])
                if axis not in ('x', 'y', 'z'):
                    raise ValueError(f"Invalid axis: {axis}")
                if self.is_corexy:
                    if axis in ('x', 'y'):
                        self.mcu.add_config_cmd("add_step_motor index=%d dir_pin=%s step_pin=%s dir_invert=%d step_invert=%d axis_index=%d" % (
                         i, dir_par["pin"], step_par["pin"], dir_invert, step_par["invert"], axis_index))
                    self.mcu.add_config_cmd("add_step_motor index=%d dir_pin=%s step_pin=%s dir_invert=%d step_invert=%d axis_index=%d" % (
                     i, dir_par["pin"], step_par["pin"], dir_invert, step_par["invert"], axis_index))

    def delay_us(self, microseconds):
        start = time.perf_counter()
        target_time = microseconds / 1000000
        while time.perf_counter() - start < target_time:
            pass

    def cmd_SOUND_ON(self, gcmd):
        self.sound = True
        self.gcode.respond_info(f"motor sound is on,self.sound = {self.sound}")
        data = {"sound": True}
        os.makedirs((os.path.dirname(self.file_path)), exist_ok=True)
        with open(self.file_path, "w") as json_file:
            json.dump(data, json_file, indent=4)

    def cmd_SOUND_OFF(self, gcmd):
        self.sound = False
        self.gcode.respond_info(f"motor sound is off,self.sound = {self.sound}")
        data = {"sound": False}
        os.makedirs((os.path.dirname(self.file_path)), exist_ok=True)
        with open(self.file_path, "w") as json_file:
            json.dump(data, json_file, indent=4)

    cmd_MUSIC_TO_START_help = "MUSIC_TO_START"

    def cmd_MUSIC_TO_START(self, gcmd):
        if self.sound:
            self.gcode.run_script_from_command(self.start_print_music)
        else:
            self.gcode.respond_info("no motor sound")

    cmd_MUSIC_TO_END_help = "MUSIC TO END"

    def cmd_MUSIC_TO_END(self, gcmd):
        if self.sound:
            self.gcode.run_script_from_command(self.end_print_music)
        else:
            self.gcode.respond_info("no motor sound")

    def cmd_MUSIC_TO_POWER(self, gcmd):
        if self.sound:
            self.gcode.run_script_from_command(self.power_on_music)
        else:
            self.gcode.respond_info("no motor sound")

    cmd_DEF_STRAT_PRINT_MUSIC_help = "DEF_STRAT_PRINT_MUSIC"

    def cmd_DEF_STRAT_PRINT_MUSIC(self, gcmd):
        self.gcode.run_script_from_command("\n        SET_STEPPER_ENABLE  STEPPER=stepper_x enable=1\n        SET_STEPPER_ENABLE  STEPPER=stepper_y enable=1\n        G4 P2000\n        MUSIC M=1 h=1 T=300\n        MUSIC M=1 h=1 T=300\n        MUSIC M=5 h=1 T=300\n        MUSIC M=5 h=1 T=300 \n        MUSIC M=6 h=1 T=300  \n        MUSIC M=6 h=1 T=300  \n        MUSIC M=5 h=1 T=400   \n        G4 P2000\n        ")

    cmd_DEF_END_PRINT_MUSIC_help = "DEF_END_PRINT_MUSIC"

    def cmd_DEF_END_PRINT_MUSIC(self, gcmd):
        self.gcode.run_script_from_command("\n        G4 P300\n        MUSIC M=4 h=1 T=300\n        MUSIC M=4 h=1 T=300\n        MUSIC M=3 h=1 T=300\n        MUSIC M=3 h=1 T=300\n        MUSIC M=2 h=1 T=300\n        MUSIC M=2 h=1 T=300\n        MUSIC M=1 h=1 T=400\n        G4 P500\n        ")

    def cmd_DEF_POWER_ON_MUSIC(self, gcmd):
        if self.print_stats.state != "printing":
            self.gcode.run_script_from_command("\n            SET_STEPPER_ENABLE  STEPPER=stepper_x enable=1\n            SET_STEPPER_ENABLE  STEPPER=stepper_y enable=1\n            G4 P2000\n            MUSIC M=1 h=1 T=150 \n            MUSIC M=2 h=1 T=150\n            MUSIC M=3 h=1 T=150\n            MUSIC M=2 h=1 T=150\n            MUSIC M=1 h=1 T=150\n            G4 P300\n            M84\n            ")

    def cmd_MUSIC(self, gcmd):
        axis = gcmd.get_int("A", 0)
        H = gcmd.get_int("H", 1)
        M = min(7, gcmd.get_int("M", 7))
        self.dir_switch = gcmd.get_int("R", 5)
        S = gcmd.get_int("S", self.fast)
        self.step_time = min(20000000, float(gcmd.get_int("T", 1000)) * 1000 / S)
        self.timer_read_time = [
         [
          39643,35318,31464,29575,26458,23572,21000],
         [
          19029,16953,15103,14196,12700,11315,10080],
         [
          9148,8150,7261,6825,6105,5439,4846]]
        self.step_us = self.timer_read_time[H][M - 1] // self.timer_read_us
        step_cnt = self.step_time // self.step_us if self.step_us != 0 else 10
        self.control_step_freq_cmd.send([self.oid, 0, int(step_cnt), self.timer_read_time[H][M - 1], self.dir_switch, axis])
        self.delay_us(self.step_time)
        self.control_step_freq_cmd.send([self.oid, 0, 0, 0, 0, axis])

    def get_status(self, eventtime):
        return {"status": (self.sound)}


def load_config(config):
    return Music(config)

